<script setup lang="ts">
import { computed,ref } from 'vue'
import { RouterLink } from 'vue-router'
import { activeUser,state,rows } from '../state/household'
import { shell } from '../state/shell'
import { summary,recent } from '../lib/selectors'
import { money,monthLabel } from '../lib/money'
import PurchaseForm from '../components/PurchaseForm.vue'
import PurchaseRows from '../components/PurchaseRows.vue'
const totals=computed(()=>summary(state.records,shell.month)),add=ref(false)
const purchases=computed(()=>recent(rows('purchases').filter(x=>x.transaction_date.slice(0,7)===shell.month)).slice(0,5))
const attention=computed(()=>rows('approval-requests').filter(r=>r.status==='open'&&r.requester_id!==activeUser.value?.id&&!rows('approval-votes').some(v=>v.request_id===r.id&&v.reviewer_id===activeUser.value?.id&&v.approved&&v.request_revision===r.revision)))
const pendingPurchases=computed(()=>state.pending.filter(x=>x.operation.kind==='purchase.create'&&x.state!=='blocked'))
</script>
<template><div class="page-heading"><div><h1 aria-label="Dashboard">A little planning, {{activeUser?.name}}.</h1><p>Here’s what’s happening with your household.</p></div><button class="button primary" @click="add=true">+ Add purchase</button></div><div class="toolbar"><label><span class="sr-only">Selected month</span><input v-model="shell.month" type="month" /></label></div><div class="metrics"><section class="card"><span class="metric-label">Allocated</span><strong class="metric-value" data-testid="allocated">{{money(totals.allocated)}}</strong><small>Your plan for {{monthLabel(shell.month)}}</small></section><section class="card"><span class="metric-label">Spent</span><strong class="metric-value" data-testid="spent">{{money(totals.spent)}}</strong><small>Server-confirmed purchases only</small></section><section class="card blush"><span class="metric-label">Allocation remaining</span><strong class="metric-value" data-testid="remaining">{{money(totals.remaining)}}</strong><small>Includes the remaining planned savings contribution</small></section></div><div v-if="pendingPurchases.length" class="notice"><strong>{{pendingPurchases.length}} purchase(s) waiting to sync.</strong> They are separate from confirmed spending above.</div><h2>Your month, together</h2><div class="grid-two"><section class="card"><div class="section-heading" style="margin-top:0"><h3>Household budget</h3><RouterLink to="/budget">View budget →</RouterLink></div><div class="progress" role="img" :aria-label="`${totals.spent} cents spent of ${totals.allocated} allocated`"><span :style="{width:Math.min(100,totals.allocated?totals.spent/totals.allocated*100:0)+'%'}" /></div><div class="summary-split"><div v-for="c in totals.rows.filter(x=>x.active&&x.kind!=='savings').slice(0,3)" :key="c.id"><small>{{c.name}}</small><strong :class="{negative:c.remaining<0}">{{money(c.remaining)}} left</strong></div></div><small>{{monthLabel(shell.month)}} · Recorded purchases only</small></section><section class="card butter"><h2>A little attention</h2><strong>{{attention.length?attention.length+' request(s) need your approval':'A little breathing room.'}}</strong><p class="text-small">{{attention.length?'Review the latest plans from your household.':'Your household’s requests are up to date.'}}</p><RouterLink to="/approvals" class="button">Review requests</RouterLink></section></div><div class="section-heading"><h2>Recent purchases</h2><RouterLink to="/purchases">View all →</RouterLink></div><section class="card"><PurchaseRows :purchases="purchases" @select="p=>$router.push('/purchases?detail='+p.id)" /></section><PurchaseForm v-if="add" @close="add=false" /></template>
